files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #0f3460;
  --highlight: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.scoreboard {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 640px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  text-align: center;
  margin-bottom: 24px;
  color: var(--highlight);
  letter-spacing: 1px;
}

.teams {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-bottom: 24px;
}

.team {
  background: var(--accent);
  border-radius: 12px;
  padding: 16px;
  text-align: center;
}

.team h2 {
  font-size: 1.125rem;
  margin-bottom: 8px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.score {
  font-size: 2.5rem;
  font-weight: 700;
  margin-bottom: 12px;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

.buttons {
  display: flex;
  gap: 8px;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  font-family: inherit;
  font-size: 1rem;
  cursor: pointer;
  border: none;
  border-radius: 8px;
  transition: background 0.15s, transform 0.1s;
}

.score-btn {
  background: var(--highlight);
  color: #fff;
  padding: 8px 12px;
  font-weight: 600;
  min-width: 48px;
}

.score-btn:hover {
  background: #ff5c7a;
}

.score-btn:active {
  transform: scale(0.95);
  background: #c73550;
}

.score-btn:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 12px;
}

.period {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--accent);
  padding: 8px 16px;
  border-radius: 8px;
}

.period span:first-child {
  color: var(--muted);
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 1px;
}

#period-display {
  font-size: 1.25rem;
  font-weight: 700;
  min-width: 1.5ch;
  text-align: center;
}

.period button {
  background: var(--highlight);
  color: #fff;
  width: 32px;
  height: 32px;
  font-size: 1.25rem;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

.period button:hover:not(:disabled) {
  background: #ff5c7a;
}

.period button:active:not(:disabled) {
  transform: scale(0.9);
}

.period button:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

.period button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.action-btn {
  background: var(--accent);
  color: var(--text);
  padding: 10px 20px;
  font-weight: 600;
}

.action-btn:hover {
  background: #1a4a7a;
}

.action-btn:active {
  transform: scale(0.95);
}

.action-btn:focus-visible {
  outline: 3px solid var(--highlight);
  outline-offset: 2px;
}

@media (max-width: 480px) {
  .teams {
    grid-template-columns: 1fr;
  }
  .scoreboard {
    padding: 16px;
  }
  .score {
    font-size: 2rem;
  }
}

(function () {
  'use strict';

  var state = {
    scores: { a: 0, b: 0 },
    period: 1,
    history: []
  };

  var scoreA = document.getElementById('score-a');
  var scoreB = document.getElementById('score-b');
  var periodDisplay = document.getElementById('period-display');
  var periodUp = document.getElementById('period-up');
  var periodDown = document.getElementById('period-down');
  var undoBtn = document.getElementById('undo-btn');
  var resetBtn = document.getElementById('reset-btn');

  function render() {
    scoreA.textContent = state.scores.a;
    scoreB.textContent = state.scores.b;
    periodDisplay.textContent = state.period;
    periodUp.disabled = state.period >= 4;
    periodDown.disabled = state.period <= 1;
    undoBtn.disabled = state.history.length === 0;
  }

  function addScore(team, points) {
    state.history.push({ team: team, points: points });
    state.scores[team] += points;
    render();
  }

  function undo() {
    var last = state.history.pop();
    if (last) {
      state.scores[last.team] -= last.points;
      render();
    }
  }

  function changePeriod(delta) {
    var next = state.period + delta;
    if (next >= 1 && next <= 4) {
      state.period = next;
      render();
    }
  }

  function reset() {
    state.scores.a = 0;
    state.scores.b = 0;
    state.period = 1;
    state.history = [];
    render();
  }

  document.querySelectorAll('.score-btn').forEach(function (btn) {
    btn.addEventListener('click', function () {
      addScore(btn.dataset.team, parseInt(btn.dataset.points, 10));
    });
  });

  periodUp.addEventListener('click', function () { changePeriod(1); });
  periodDown.addEventListener('click', function () { changePeriod(-1); });
  undoBtn.addEventListener('click', undo);
  resetBtn.addEventListener('click', reset);

  render();
})();
